function today(value) { if (!value) return false; const date = new Date(value), now = new Date(); return date.toDateString() === now.toDateString(); }
function saveActivities() { localStorage.setItem("luvit:activities:v1", JSON.stringify(store.get().activities.slice(0, 30))); }
function addActivity(text) { store.update(state => { state.activities.unshift({ id: uid(), text, at: new Date().toISOString() }); state.activities = state.activities.slice(0, 30); return state; }, "activity"); saveActivities(); }
function hydrateIcons(root = document) { qsa("[data-icon]", root).forEach(slot => { const name = slot.dataset.icon; slot.replaceWith(icon(name)); }); }
hydrateIcons();

async function persistStops(reason = "Alterações salvas") {
  store.set({ sync: userId ? "syncing" : "local" }, "sync");
  try { await persistDeliveries(store.get().deliveries, userId); store.set({ sync: userId ? "synced" : "local", lastSyncAt: new Date().toISOString() }, "sync"); }
  catch (error) { console.error("[Luvit sync]", error); store.set({ sync: navigator.onLine ? "error" : "pending" }, "sync"); }
  if (reason) addActivity(reason);
}
async function persistFavoriteList() { try { await persistFavorites(store.get().favorites, userId); } catch (error) { console.error("[Luvit favorites]", error); } }

