function renderCompactRoutes() { const target = qs("#recent-routes"); target.replaceChildren(); const routes = store.get().history.slice(0, 4); if (!routes.length) return target.append(el("div", "compact-empty", "Nenhuma rota finalizada.")); routes.forEach(route => { const row = el("div", "compact-row"), copy = el("div"); copy.append(el("b", "", route.name || "Rota concluída"), el("small", "", `${formatDate(route.completedAt || route.completed_at)} · ${formatDistance(route.distance || route.total_distance_meters)}`)); row.append(copy, statusBadge("completed")); target.append(row); }); }
