function filteredStops() { const state = store.get(), term = normalize(state.stopSearch); return state.deliveries.filter(stop => { const matchesSearch = !term || normalize(`${stop.address} ${stop.neighborhood || ""} ${stop.city || ""} ${stop.notes || ""}`).includes(term); const matchesFilter = state.stopFilter === "all" || state.stopFilter === "problem" && (stop.status === "problem" || stop.latitude == null) || stop.status === state.stopFilter; return matchesSearch && matchesFilter; }); }
