function selectStop(id) { store.set({ selectedStopId: id }, "select-stop"); if (innerWidth <= 980) openStopSheet(id); else plannerMap && drawRoute(plannerMap, store.get().start, store.get().deliveries, store.get().routeGeometry?.geometry, { selectedStopId: id, onSelectStop: selectStop, fit: false }); const item = qs(`.stop-item[data-id="${CSS.escape(id)}"]`); item?.scrollIntoView({ block: "nearest" }); }

function setView(view) { const state = store.get(); if (view === "active" && !state.activeRoute) view = "planner"; store.set({ view }, "view"); qs("#sidebar").classList.remove("mobile-open"); qs("#mobile-menu-button").setAttribute("aria-expanded", "false"); if (view === "planner" && (window.innerWidth > 768 || store.get().plannerTab === "map")) requestAnimationFrame(() => ensurePlannerMap()); if (view === "active") requestAnimationFrame(renderDriverMap); }
function renderAll(_, reason) { renderShell(); if (reason !== "select-stop") renderDashboard(); renderPlanner(); renderHistory(); renderFavorites(); renderDriver(); }
store.subscribe(renderAll);

function resetDrawer() { drawerMode = "create"; drawerEditingId = null; drawerSelection = null; qs("#drawer-title").textContent = "Adicionar parada"; qs("#stop-form").reset(); qs("#address-preview").hidden = true; qs("#drawer-message").textContent = ""; drawerAutocomplete?.setSelected(null); drawerAutocomplete?.close(true); }
