function fillDrawer(data) { qs("#drawer-address").value = data.address || ""; qs("#drawer-street").value = data.street || String(data.address || "").split(/[,—]/)[0]; qs("#drawer-number").value = data.number || ""; qs("#drawer-complement").value = data.complement || ""; qs("#drawer-neighborhood").value = data.neighborhood || ""; qs("#drawer-city").value = data.city || ""; qs("#drawer-state").value = data.state || ""; qs("#drawer-postcode").value = data.postcode || ""; qs("#drawer-notes").value = data.notes || ""; }
function showAddressPreview(data) { qs("#address-preview").hidden = false; qs("#preview-address").textContent = data.label || data.address; qs("#preview-detail").textContent = data.detail || [data.neighborhood, data.city, data.state].filter(Boolean).join(" · "); }
function drawerData() { const selected = drawerSelection || {}; const street = qs("#drawer-street").value.trim(), number = qs("#drawer-number").value.trim(), details = [qs("#drawer-neighborhood").value.trim(), [qs("#drawer-city").value.trim(), qs("#drawer-state").value.trim()].filter(Boolean).join(" - "), qs("#drawer-postcode").value.trim()].filter(Boolean).join(" · "); const manualAddress = [[street, number].filter(Boolean).join(", "), details].filter(Boolean).join(" — "); return { ...selected, address: selected.address || manualAddress || qs("#drawer-address").value.trim(), street, number, complement: qs("#drawer-complement").value.trim(), neighborhood: qs("#drawer-neighborhood").value.trim(), city: qs("#drawer-city").value.trim(), state: qs("#drawer-state").value.trim(), postcode: qs("#drawer-postcode").value.trim(), notes: qs("#drawer-notes").value.trim() }; }
async function validateDrawerAddress(buttonElement) { let data = drawerData(); if (data.latitude != null && normalize(data.address) === normalize(qs("#drawer-address").value || data.address)) return data; setLoading(buttonElement, true, "Localizando..."); try { const found = await geocode(qs("#drawer-address").value.trim() || data.address, store.get().start); if (!found) throw new Error("NOT_FOUND"); drawerSelection = { ...data, ...found }; fillDrawer(drawerSelection); showAddressPreview(drawerSelection); return drawerSelection; } finally { setLoading(buttonElement, false); } }
