  catch (error) { console.error("[Luvit stop form]", error); qs("#drawer-message").textContent = error.message === "OFFLINE" ? "Você está offline. Escolha uma sugestão já carregada ou tente novamente quando reconectar." : "Endereço não localizado. Confira rua, número e cidade ou marque o ponto no mapa."; }
